      <AiTodoList>
        {items.map((item, index) => (
          <AiTodoItem
            key={item.title}
            {...item}
            onStatusChange={(status) =>
              setItems((current) =>
                current.map((entry, itemIndex) =>
                  itemIndex === index ? { ...entry, status } : entry
                )
              )
            }
          />
        ))}
      </AiTodoList>
    </AiTodo>
